<script setup lang="ts">
import { ref, reactive } from 'vue';
import Icon from './components/Icon.vue';
import AdjustmentHistory from './components/AdjustmentHistory.vue';
import { preferences, uuid, dataSize, bytesLabel, lastSaved, timeLabel, storageError, savedRevision } from './state';
import { aiConnections, activeAiConnectionId, type AiProtocol, type AiConnection } from './ai';
import type { DirectoryHandle } from './directory';
const props = defineProps<{ directory?: DirectoryHandle; directoryBusy: boolean; directorySupported: boolean; directorySupportMessage: string; directoryWriteLabel: string; qualityModes: readonly { id: string; title: string; caption: string; detail: string }[]; askDelete: (text: string) => Promise<boolean> }>();
const emit = defineEmits<{ notice: [text: string]; openModal: [name: string]; bind: []; save: []; read: []; unbind: [] }>();
const aiEditingId = ref('');
const aiConnectionForm = reactive<AiConnection>({ id: '', name: '', protocol: 'responses', baseUrl: 'https://api.openai.com/v1', model: 'gpt-6-astra', apiKey: '', enabled: true });
const aiConnectionError = ref('');
const protocolLabel = (protocol: AiProtocol) => protocol === 'responses' ? 'Responses' : 'Chat Completions';
function resetAiConnectionForm() { Object.assign(aiConnectionForm, { id: '', name: '', protocol: 'responses', baseUrl: 'https://api.openai.com/v1', model: 'gpt-6-astra', apiKey: '', enabled: true }); aiEditingId.value = ''; aiConnectionError.value = ''; }
function editAiConnection(connection: AiConnection) { Object.assign(aiConnectionForm, connection); aiEditingId.value = connection.id; aiConnectionError.value = ''; }
function newAiConnection() { resetAiConnectionForm(); aiConnectionForm.name = `本地接口 ${aiConnections.length + 1}`; aiConnectionForm.baseUrl = 'http://127.0.0.1:11434/v1'; aiConnectionForm.model = ''; }
function saveAiConnection() {
  aiConnectionError.value = '';
  if (!aiConnectionForm.name.trim() || !aiConnectionForm.baseUrl.trim() || !aiConnectionForm.model.trim()) { aiConnectionError.value = '请填写名称、Base URL 和模型 ID。'; return; }
  try { const parsed = new URL(aiConnectionForm.baseUrl.trim()); if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error(); } catch { aiConnectionError.value = 'Base URL 必须是有效的 http(s) 地址。'; return; }
  const values = { ...aiConnectionForm, name: aiConnectionForm.name.trim(), baseUrl: aiConnectionForm.baseUrl.trim().replace(/\/+$/, ''), model: aiConnectionForm.model.trim(), apiKey: aiConnectionForm.apiKey.trim() };
  const index = aiConnections.findIndex(row => row.id === aiEditingId.value);
  if (index >= 0) aiConnections[index] = values;
  else { values.id = uuid(); aiConnections.push(values); }
  activeAiConnectionId.value = values.id;
  resetAiConnectionForm(); emit('notice', 'AI 接口配置已保存。');
}
async function deleteAiConnection(id: string) { const index = aiConnections.findIndex(row => row.id === id); if (index < 0 || !await props.askDelete('删除这条 AI 接口配置？')) return; aiConnections.splice(index, 1); if (activeAiConnectionId.value === id) activeAiConnectionId.value = aiConnections.find(row => row.enabled)?.id || ''; if (aiEditingId.value === id) resetAiConnectionForm(); emit('notice', 'AI 接口配置已删除。'); }
function toggleAiConnection(connection: AiConnection) { connection.enabled = !connection.enabled; if (!connection.enabled && activeAiConnectionId.value === connection.id) activeAiConnectionId.value = aiConnections.find(row => row.enabled)?.id || ''; if (connection.enabled && !activeAiConnectionId.value) activeAiConnectionId.value = connection.id; }
</script>
<template>
          <div class="page-heading"><div><div class="eyebrow">个人设置</div><h1>按你的习惯，安放学习空间。</h1><p>手动选择一个目录，让资料结构独立于设备和浏览器。</p></div></div>
          <div class="settings-grid"><div class="settings-main"><section class="panel settings-card"><div class="section-heading"><h2><Icon name="folder" :size="21" /> 本地工作区目录</h2><span class="tiny-badge">手动选择</span></div><div class="directory-box"><span class="space-icon sage"><Icon name="folder" :size="25" /></span><div><strong>{{ directory?.name || '尚未选择工作区目录' }}</strong><p>{{ directory ? `目录句柄保存在当前浏览器 · ${directoryWriteLabel}` : '建议选择一个专用于知序的空文件夹' }}</p></div><span v-if="directory" class="status-dot"></span></div><div class="inline-actions"><button class="button secondary" :disabled="!directorySupported" @click="$emit('bind')">{{ directory ? '更换目录' : '选择目录' }}</button><button v-if="directory" class="button primary" :disabled="directoryBusy" @click="$emit('save')">{{ directoryBusy ? '处理中…' : '将浏览器内容写入目录' }}</button><button v-if="directory" class="button secondary" :disabled="directoryBusy" @click="$emit('read')">从目录读取</button><button v-if="directory" class="text-link" @click="$emit('unbind')">解除选择</button><RouterLink v-if="!directorySupported" to="/planner/sync" class="text-link">下载讨论接续包</RouterLink></div><p class="help-text">{{ directorySupportMessage }}</p><div class="path-examples"><span>入口 <code>workspace.md</code></span><span>索引 <code>_index.tsv</code></span><span>关系 <code>graph/edges.tsv</code></span><small>正文按 goals、actions、progress、evidence、drafts、reviews 分目录保存为 Markdown。</small></div></section>
          <AdjustmentHistory />
          <section class="panel settings-card ai-connections-card"><div class="section-heading"><h2><Icon name="spark" :size="21" /> AI 接口配置</h2><span class="tiny-badge">{{ aiConnections.length }} 个连接</span></div><p class="help-text">按标准 OpenAI 兼容接口配置多个云端或本地服务。每次 AI 规划只使用当前选中的连接，接口会在本机代理请求。</p><div v-if="aiConnections.length" class="ai-connection-list"><article v-for="connection in aiConnections" :key="connection.id" class="ai-connection-row" :class="{ active: activeAiConnectionId === connection.id, disabled: !connection.enabled }"><div class="ai-connection-main"><label><input v-model="activeAiConnectionId" type="radio" name="active-ai-connection" :value="connection.id" :disabled="!connection.enabled"><strong>{{ connection.name }}</strong></label><span class="tiny-badge">{{ protocolLabel(connection.protocol) }}</span><span class="connection-state" :class="{ enabled: connection.enabled }">{{ connection.enabled ? '已启用' : '已停用' }}</span></div><small>{{ connection.baseUrl }} · {{ connection.model }}</small><div class="record-actions"><button class="text-link" @click="editAiConnection(connection)">调整</button><button class="text-link" @click="toggleAiConnection(connection)">{{ connection.enabled ? '停用' : '启用' }}</button><button class="text-link danger" @click="deleteAiConnection(connection.id)">删除</button></div></article></div><div v-else class="empty-state ai-empty">还没有 AI 接口。新增一个连接后，AI 规划页才会启用。</div><div class="ai-connection-form"><div class="form-columns"><label>连接名称<input v-model="aiConnectionForm.name" maxlength="80" placeholder="例如：本地 LM Studio"></label><label>协议<select v-model="aiConnectionForm.protocol"><option value="responses">OpenAI Responses</option><option value="chat_completions">OpenAI Chat Completions</option></select></label></div><label>Base URL<input v-model="aiConnectionForm.baseUrl" maxlength="500" placeholder="https://api.openai.com/v1 或 http://127.0.0.1:11434/v1"><small>可以填写 `/v1` 基地址；系统会按协议补上 `/responses` 或 `/chat/completions`。</small></label><div class="form-columns"><label>模型 ID<input v-model="aiConnectionForm.model" maxlength="200" placeholder="例如：gpt-6-astra、deepseek-chat、qwen2.5"></label><label>API Key（可留空）<input v-model="aiConnectionForm.apiKey" type="password" autocomplete="off" maxlength="500" placeholder="仅保存在本机浏览器设置"><small>本地原型会保存在浏览器设置中，正式版改为后端加密保存。</small></label></div><div class="inline-actions"><button class="button primary" @click="saveAiConnection">{{ aiEditingId ? '保存接口修改' : '添加 AI 接口' }}</button><button v-if="aiEditingId" class="button secondary" @click="resetAiConnectionForm">取消编辑</button></div><p v-if="aiConnectionError" class="form-error" role="alert">{{ aiConnectionError }}</p></div></section>
          <section class="panel settings-card"><div class="section-heading"><h2><Icon name="spark" :size="21" /> 讨论资料深度</h2></div><p class="help-text mode-intro">控制接续包选取的资料数量与摘录长度。档位用于准备上下文，不会切换外部 AI 模型或推理模式。</p><div class="mode-options"><label v-for="mode in qualityModes" :key="mode.id" :class="{ checked: preferences.mode === mode.id }"><input v-model="preferences.mode" type="radio" name="quality-mode" :value="mode.id"><strong>{{ mode.title }}<Icon v-if="preferences.mode === mode.id" name="check" :size="15" /></strong><span>{{ mode.caption }}</span><small>{{ mode.detail }}</small></label></div><p class="help-text">方向和行动记录始终保留；资料按最近录入选取。AI 提案会在本地汇总阶段记录，并按整次请求的字节预算选取明细。</p></section></div>
          <aside class="settings-aside"><section class="panel settings-card local-summary"><h2>保存与备份</h2><strong class="storage-size">{{ bytesLabel(dataSize) }}</strong><span class="small muted">当前浏览器中的结构化数据</span><p>最近成功保存到浏览器<br><strong>{{ lastSaved ? timeLabel(lastSaved) : '暂无时间记录' }}</strong></p>
            <p>目录备份<br><strong>{{ directoryWriteLabel }}</strong></p>
            <p v-if="storageError || (lastSaved && savedRevision !== preferences.directoryWrite?.revision)" class="help-text">可将当前工作区写入目录，保留一份备份。</p></section><section class="prototype-note"><h3>关于目录结构</h3><p>索引负责一致性，Markdown 便于人和 AI 阅读，关系表为未来的目标图与证据图预留入口。</p><p>浏览器保存和目录写入是两步操作；当前不会监听文件夹变化。</p><div class="stacked-actions"><button class="text-link" @click="$emit('openModal', 'reset')">载入浏览器内示例</button><button class="text-link danger" @click="$emit('openModal', 'clear')">清空浏览器工作区</button></div></section></aside></div>
        </template>
